class Solution {
public:
    bool repeatedStringMatch(string a, string b, int x, int y) {
        int A = (int)a.size();
        int B = (int)b.size();

        long long N = 1LL * A * x;          // total length of a repeated x times
        long long L = 1LL * B * y;          // total length of b repeated y times
        if (L > N) return false;           // impossible to fit

        // compute lcm(A, B) safely
        int g = gcd(A, B);
        int lcm = A / g * B;                // fits in int because A,B ≤ 100

        // try every possible offset modulo A
        for (int offset = 0; offset < A; ++offset) {
            if (offset + L > N) continue;   // not enough room from this start

            int limit = (int)min<long long>(L, lcm);
            bool ok = true;
            for (int t = 0; t < limit; ++t) {
                char ca = a[(offset + t) % A];
                char cb = b[t % B];
                if (ca != cb) { ok = false; break; }
            }
            if (ok) return true;            // the whole b*y matches here
        }
        return false;
    }
};
